import{Rt as e,dt as t,mt as n,n as r}from"./chunks/framework.BkIgthgQ.js";var i=JSON.parse(`{"title":"Delta engines","description":"hdiffpatch CGO HDIFF13& vs historical KVDIFFHP1. Magic dispatch. C++ toolchain to build.","frontmatter":{"title":"Delta engines","description":"hdiffpatch CGO HDIFF13& vs historical KVDIFFHP1. Magic dispatch. C++ toolchain to build."},"headers":[],"relativePath":"en/contribute/delta.md","filePath":"en/contribute/delta.md","lastUpdated":1790057721000}`),a={name:`en/contribute/delta.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="delta-engines" tabindex="-1">Delta engines <a class="header-anchor" href="#delta-engines" aria-label="Permalink to “Delta engines”">​</a></h1><p>Single-file binary deltas live in <code>internal/delta</code>. The server <strong>must</strong> build with <code>CGO_ENABLED=1</code> and a C++ toolchain (Windows MinGW <code>g++</code> / Linux <code>g++</code> or <code>clang++</code> / macOS Xcode <code>clang++</code>). It does not exec <code>hdiffz</code>/<code>hpatchz</code> from PATH at runtime. The Go SDK stays <code>CGO_ENABLED=0</code>; see the SDK pages.</p><table tabindex="0"><thead><tr><th>Algorithm</th><th>Magic</th><th>Notes</th></tr></thead><tbody><tr><td>hdiffpatch (CGO)</td><td><code>HDIFF13&amp;</code></td><td>New diffs are uncompressed official HDIFF13; <code>DescribeAvailable</code> is <code>cgo</code></td></tr><tr><td>Historical hdiffpatch</td><td><code>KVDIFFHP1</code></td><td>Patch-only; not official <code>.hdiff</code></td></tr><tr><td>bsdiff</td><td><code>BSDIFF40</code></td><td><code>pure-go</code></td></tr><tr><td>xdelta3 / VCDIFF</td><td><code>D6 C3 C4</code></td><td>RFC 3284 binary magic, not ASCII; <code>pure-go</code></td></tr></tbody></table><p><code>Patch</code> dispatches on magic; never cross-decode. Unknown admin algo → <code>DELTA_ALGO_UNSUPPORTED</code>. Admin <code>POST .../artifacts/delta</code> enqueues a Job. HTTP handlers must not import <code>archive/zip</code>.</p><p>Official <code>darwin/*</code> binaries must be CGO-built on a macOS host (<code>darwin/arm64</code> natively, <code>darwin/amd64</code> same-host <code>clang -arch x86_64</code>); never a Linux→darwin CGO cross without an Apple SDK. The GitHub release workflow builds both on a pinned macOS runner (<code>macos-15</code>). GitHub is the only forge, so no target is ever skipped for lack of a host: if an artifact is missing, the packaging job fails instead of fabricating a file.</p>`,5)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};